import { readFileSync } from 'node:fs';
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore — generated by scripts/build-wasm.sh (wasm-bindgen)
import * as glue from '../../wasm-pkg/anonymiser_wasm';

let ready = false;

export const realWasm = (): typeof glue => {
    if (!ready) {
        const url = new URL('../../wasm-pkg/anonymiser_wasm_bg.wasm', import.meta.url);
        glue.initSync({ module: readFileSync(url) });
        ready = true;
    }
    return glue;
};

export const realTableCodec = () => {
    const g = realWasm();
    return {
        TableDecoder: g.TableDecoder,
        encode_table_header: g.encode_table_header,
        encode_table_rows: g.encode_table_rows,
    };
};

export const realKeyMaterial = () => realWasm().policy_key_material;
